56	bool FeatureRegistry::registerFeature(const FeatureDescription* description)
57	{
58	    if (!description)
59	        return false;
60	
61	    if (description->name != nullptr) {
62	        registeredFeatures_[description->name] = description;
63	        // invoke onRegister callback
64	        FEATURE_LOG_DEBUG("registered feature: %s", description->name);
65	        if (description->native_callbacks && description->native_callbacks->onRegister) {
66	            FEATURE_LOG_DEBUG("invoke onRegister callback...");
67	            description->native_callbacks->onRegister(description->name);
68	        }
69	        // register for wamr
70	        if (onFeatureRegistered_)
71	            if (!onFeatureRegistered_(description))
72	                return false;
73	        return true;
74	    }
75	    return false;
76	}
