78	void FeatureRegistry::unregisterAllFeatures()
79	{
80	    for (const auto& item : registeredFeatures_) {
81	        const auto& description = item.second;
82	        if (description && description->native_callbacks && description->native_callbacks->onUnregister) {
83	            description->native_callbacks->onUnregister(description->name);
84	        }
85	    }
86	}
