599	ft_value_t FeatureManagerQjs::featureRequire(ft_value_t binding_obj, const char* name)
600	{
601	    FEATURE_LOG_DEBUG("featureRequire for '%s'", name);
602	    ft_context_ref ft_ctx = getFeatureContext();
603	    FEATURE_CHECK_NE(ft_ctx, nullptr);
604	    ft_value_t ret;
605	    auto js_ret_ptr = FT_VAL_GET_JS_VAL_PTR(ret);
606	    *js_ret_ptr = FEATURE_VALUE_UNDEFINED;
607	    auto pDesc = getFeatureRegistry()->findFeature(name);
608	    if (!pDesc) {
609	        FEATURE_LOG_DEBUG("can't find native feature '%s', fallback to original JS module load!", name);
610	        return ret;
611	    }
612	
613	    auto& prototypes = getFeaturePrototypes();
614	
615	    auto& prototype = prototypes[name];
616	    if (!prototype) {
617	        // create proto
618	        prototype = new FeaturePrototypeQjs(pDesc);
619	        prototype->setFeatureManager(this);
620	        setPackageName(getFeatureRegistry()->getFeaturePackageName());
621	        setEnvName(FEATURE_ENV_NAME);
622	    }
623	
624	    // create feature instance for the required object
625	    FeatureObjectUniquePtr<FeatureInstanceQjs> instance(new FeatureInstanceQjs(prototype));
626	    auto instance_ptr = instance.get();
627	    // save binding_obj into instance
628	    auto js_binding_obj = FT_VAL_GET_JS_VAL(binding_obj);
629	    instance->setVmObject(js_binding_obj);
630	
631	    // insert into instances array, update iid
632	    int iid = prototype->addInstance(std::move(instance));
633	    instance_ptr->setInstanceId(iid);
634	
635	    auto js_instance = createJsInstance((FeaturePrototypeQjs*)prototype, instance_ptr);
636	    if (pDesc->native_callbacks && pDesc->native_callbacks->onRequired) {
637	        FEATURE_LOG_DEBUG("invoke onRequired callback...");
638	#ifdef CONFIG_FEATURE_ENABLE_TRACKER
639	        auto& feature_tracker = prototype->featureTracker();
640	        feature_tracker.begin("onRequired");
641	#endif
642	        auto ctx = (feature_context_ref)ft_context_get_data(ft_ctx);
643	        pDesc->native_callbacks->onRequired(ctx, instance_ptr);
644	#ifdef CONFIG_FEATURE_ENABLE_TRACKER
645	        feature_tracker.end("onRequired");
646	#endif
647	    }
648	    *js_ret_ptr = js_instance;
649	    return ret;
650	}
