661	void FeatureManagerQjs::uninit()
662	{
663	    auto ft_ctx = getFeatureContext();
664	    if (!ft_ctx) {
665	        FEATURE_LOG_WARN("ft_ctx is missing");
666	        delete getFeatureRegistry();
667	        return;
668	    }
669	
670	    clearClearables();
671	    detachFeatureInstances();
672	
673	    JSContext* js_ctx = (JSContext*)ft_context_get_data(ft_ctx);
674	    auto free_prototype = [js_ctx](FeaturePrototypeQjs* prototype) {
675	        auto js_proto_ptr = FT_VAL_GET_JS_VAL_PTR(prototype->ft_proto());
676	        if (!feature_is_undefined(*js_proto_ptr)) {
677	            uninit_prototype(js_ctx, prototype->description(), *js_proto_ptr);
678	            feature_free_value(js_ctx, *js_proto_ptr);
679	            *js_proto_ptr = FEATURE_VALUE_UNDEFINED;
680	        }
681	    };
682	
683	    for (const auto& pair : getFeaturePrototypes()) {
684	        auto proto = static_cast<FeaturePrototypeQjs*>(pair.second);
685	        auto description = getFeatureRegistry()->findFeature(pair.first.c_str());
686	        FEATURE_CHECK_NE(description, nullptr);
687	        if (!proto)
688	            continue;
689	
690	        for (auto& proto_pair : proto->children()) {
691	            // clear all interface instances belongs to this instance.
692	            auto child_proto = static_cast<FeaturePrototypeQjs*>(proto_pair.second.get());
693	            child_proto->clearAllInstances();
694	            FEATURE_LOG_INFO("free interface prototype '%s'", proto_pair.first);
695	            free_prototype(child_proto);
696	        }
697	
698	        // clear all feature instance at first, it will free all feature instance and call onDetach for them
699	        proto->clearAllInstances();
700	        // call feature's onDestroy
701	        if (description->native_callbacks && description->native_callbacks->onDestroy) {
702	            FEATURE_LOG_DEBUG("invoke onDestroy callback...");
703	#ifdef CONFIG_FEATURE_ENABLE_TRACKER
704	            auto& feature_tracker = proto->featureTracker();
705	            feature_tracker.begin("onDestroy");
706	#endif
707	            description->native_callbacks->onDestroy(js_ctx, proto);
708	#ifdef CONFIG_FEATURE_ENABLE_TRACKER
709	            feature_tracker.end("onDestroy");
710	#endif
711	        }
712	        FEATURE_LOG_DEBUG("free feature prototype '%s'", description->name);
713	        free_prototype(proto);
714	        delete proto;
715	    }
716	
717	    // uninit registery
718	    delete getFeatureRegistry();
719	    ReleaseFeatureContextQjs(ft_ctx);
720	    setFeatureContext(nullptr);
721	}
