726	    ft_context_ref ft_ctx = getFeatureContext();
727	    FEATURE_CHECK_NE(ft_ctx, nullptr);
728	    ft_value_t ret;
729	    auto js_ret_ptr = FT_VAL_GET_JS_VAL_PTR(ret);
730	    *js_ret_ptr = FEATURE_VALUE_UNDEFINED;
731	    const FeatureDescription* pDesc = getFeatureRegistry()->findFeature(name);
732	    if (!pDesc) {
733	        FEATURE_LOG_WARN("can't find description for native feature '%s'!", name);
734	        return ret;
735	    }
736	
737	    // create proto
738	    auto& prototype = getFeaturePrototypes()[pDesc->name];
739	    if (!prototype) {
740	        prototype = new FeaturePrototypeQjs(pDesc);
741	        prototype->setFeatureManager(this);
742	        setPackageName(getFeatureRegistry()->getFeaturePackageName());
743	        setEnvName(FEATURE_ENV_NAME);
744	    }
745	
746	    if (!ensureJsPrototype((FeaturePrototypeQjs*)prototype)) {
747	        FEATURE_LOG_ERROR("ensure js prototype failed !");
748	        return ret;
