750	
751	    auto js_proto = FT_VAL_GET_JS_VAL(((FeaturePrototypeQjs*)prototype)->ft_proto());
752	    auto ctx = (feature_context_ref)ft_context_get_data(ft_ctx);
753	    *js_ret_ptr = feature_dup_value(ctx, js_proto);
754	    return ret;

